'use strict';

// The pure-JS fallback. It is SAFE, and it is only ever this binding's
// INITIALIZER -- never, on its own, the value the package publishes.
//
// It is deliberately ANONYMOUS, which is what makes it dangerous: source
// indexing names a function expression after the variable it is assigned
// to, so this node is indexed under the name "dangerousOp" -- a perfect
// same-file match, under the exact export name the advisory asks for, for
// a name-based export attribution. Nothing else in this package carries
// that name, because the real implementation is anonymous too.
let dangerousOp = function (input) {
  return 'safe:' + String(input);
};

// The native addon takes over when it loaded. Whether it did is a
// property of the INSTALL and the ENVIRONMENT; no reader of this file can
// decide it.
if (process.env.VT2_NATIVE === '1') {
  dangerousOp = require('./native');
}

// GHSA-vt2v2-0001 names THIS export, and by this line the fallback above
// may well have been replaced.
exports.dangerousOp = dangerousOp;

// The explicit escape hatch, for callers that already know the addon is
// present. Whenever the branch above ran this is the SAME function object
// as `dangerousOp` -- and unlike it, this one is statically resolvable
// (RWF-004a), so the call graph reaches native.js's real function through
// this name and never through the stale-aliased one.
exports.dangerousOpNative = require('./native');
